create or replace function public.record_audit_event(p_actor_id uuid,p_action text,p_entity_type text,p_entity_id text default null,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.audit_logs(actor_id,action,entity_type,entity_id,metadata) values(p_actor_id,p_action,p_entity_type,p_entity_id,coalesce(p_metadata,'{}'::jsonb)); end; $$;
revoke all on function public.record_audit_event(uuid,text,text,text,jsonb) from public,anon,authenticated;
create or replace function public.audit_row_change() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare row_data jsonb; entity_id text; actor uuid; meta jsonb; begin row_data:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end; entity_id:=row_data->>'id'; actor:=auth.uid(); meta:=jsonb_strip_nulls(jsonb_build_object('operation',tg_op,'status',row_data->>'status','delivery_status',row_data->>'delivery_status','payment_status',row_data->>'payment_status','seller_status',row_data->>'seller_status','priority',row_data->>'priority','price',row_data->>'price','enabled',row_data->>'enabled','is_active',row_data->>'is_active','rollout_percent',row_data->>'rollout_percent')); perform public.record_audit_event(actor,lower(tg_op)||'_'||tg_table_name,tg_table_name,entity_id,meta); return coalesce(new,old); end; $$;
revoke all on function public.audit_row_change() from public,anon,authenticated;
drop trigger if exists audit_orders on public.orders; create trigger audit_orders after insert or update or delete on public.orders for each row execute function public.audit_row_change();
drop trigger if exists audit_products on public.products; create trigger audit_products after insert or update or delete on public.products for each row execute function public.audit_row_change();
drop trigger if exists audit_shipments on public.shipments; create trigger audit_shipments after insert or update or delete on public.shipments for each row execute function public.audit_row_change();
drop trigger if exists audit_support_tickets on public.support_tickets; create trigger audit_support_tickets after insert or update or delete on public.support_tickets for each row execute function public.audit_row_change();
drop trigger if exists audit_memberships on public.memberships; create trigger audit_memberships after insert or update or delete on public.memberships for each row execute function public.audit_row_change();
drop trigger if exists audit_wallet_transactions on public.wallet_transactions; create trigger audit_wallet_transactions after insert or update or delete on public.wallet_transactions for each row execute function public.audit_row_change();
drop trigger if exists audit_reward_transactions on public.reward_transactions; create trigger audit_reward_transactions after insert or update or delete on public.reward_transactions for each row execute function public.audit_row_change();
drop trigger if exists audit_feature_flags on public.feature_flags; create trigger audit_feature_flags after insert or update or delete on public.feature_flags for each row execute function public.audit_row_change();
create or replace function public.admin_list_audit_logs(p_limit integer default 100) returns table(id bigint,actor_id uuid,actor_name text,action text,entity_type text,entity_id text,metadata jsonb,created_at timestamptz) language sql stable security definer set search_path=public,pg_temp as $$ select a.id,a.actor_id,coalesce(p.full_name,u.email::text,'System'),a.action,a.entity_type,a.entity_id,a.metadata,a.created_at from public.audit_logs a left join public.profiles p on p.id=a.actor_id left join auth.users u on u.id=a.actor_id where exists(select 1 from public.profiles me where me.id=auth.uid() and me.role='admin') order by a.created_at desc limit greatest(1,least(coalesce(p_limit,100),500)); $$;
revoke all on function public.admin_list_audit_logs(integer) from public,anon; grant execute on function public.admin_list_audit_logs(integer) to authenticated;
create or replace function public.admin_observability_summary() returns jsonb language sql stable security definer set search_path=public,pg_temp as $$ select jsonb_build_object('generated_at',now(),'audit_events_24h',(select count(*) from public.audit_logs where created_at>=now()-interval '24 hours'),'analytics_events_24h',(select count(*) from public.analytics_events where created_at>=now()-interval '24 hours'),'shipments_total',(select count(*) from public.shipments),'failed_shipments',(select count(*) from public.shipments where status in ('failed','rto','cancelled','exception')),'open_returns',(select count(*) from public.return_requests where status in ('requested','approved','pickup_scheduled','picked_up','in_transit')),'failed_webhooks_24h',(select count(*) from public.webhook_deliveries where status='failed' and created_at>=now()-interval '24 hours'),'unhealthy_checks',(select count(*) from public.platform_health_checks where status in ('unhealthy','degraded') and checked_at>=now()-interval '24 hours')) where exists(select 1 from public.profiles me where me.id=auth.uid() and me.role='admin'); $$;
revoke all on function public.admin_observability_summary() from public,anon; grant execute on function public.admin_observability_summary() to authenticated;